using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace Macaron.DependencyInjection.Generator;

[Generator]
public sealed class DependencyInjectionGenerator : IIncrementalGenerator
{
    private const string RegistrationExtensionsSource =
        """
        // <auto-generated />
        #nullable enable

        namespace Macaron.DependencyInjection
        {
            internal static class DependencyRegistrarExtensions
            {
                internal static void Register<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    global::Macaron.DependencyInjection.Lifetime lifetime,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, lifetime, tag, cleanup);
                }

                internal static void RegisterTransient<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, global::Macaron.DependencyInjection.Lifetime.Transient, tag, cleanup);
                }

                internal static void RegisterScoped<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, global::Macaron.DependencyInjection.Lifetime.Scoped, tag, cleanup);
                }

                internal static void RegisterSingleton<T>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<T>? cleanup = null)
                    where T : notnull
                {
                    Register<T, T>(registrar, global::Macaron.DependencyInjection.Lifetime.Singleton, tag, cleanup);
                }

                internal static void Register<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    global::Macaron.DependencyInjection.Lifetime lifetime,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    var factory = global::Macaron.DependencyInjection.Generated.Factories.Get<TImplementation>();

                    global::Macaron.DependencyInjection.DependencyFactory<TService> serviceFactory =
                        (global::Macaron.DependencyInjection.IDependencyResolver resolver, ref global::Macaron.DependencyInjection.CleanupCollector collector) =>
                        {
                            return factory(resolver, ref collector);
                        };

                    global::Macaron.DependencyInjection.IDependencyRegistrarExtensions.Register<TService>(
                        registrar,
                        serviceFactory,
                        lifetime,
                        tag,
                        cleanup);
                }

                internal static void RegisterTransient<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    Register<TService, TImplementation>(
                        registrar,
                        global::Macaron.DependencyInjection.Lifetime.Transient,
                        tag,
                        cleanup);
                }

                internal static void RegisterScoped<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    Register<TService, TImplementation>(
                        registrar,
                        global::Macaron.DependencyInjection.Lifetime.Scoped,
                        tag,
                        cleanup);
                }

                internal static void RegisterSingleton<TService, TImplementation>(
                    this global::Macaron.DependencyInjection.IDependencyRegistrar registrar,
                    object? tag = null,
                    global::System.Action<TService>? cleanup = null)
                    where TService : notnull
                    where TImplementation : notnull, TService
                {
                    Register<TService, TImplementation>(
                        registrar,
                        global::Macaron.DependencyInjection.Lifetime.Singleton,
                        tag,
                        cleanup);
                }
            }
        }

        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static output =>
        {
            var hintName = HintNameHelper.GetAssemblyHintName(
                sourceName: "DependencyRegistrarExtensions",
                assemblyIdentity: typeof(DependencyInjectionGenerator).Assembly.FullName
            );

            output.AddSource(
                hintName: $"{hintName}.g.cs",
                sourceText: SourceText.From(RegistrationExtensionsSource, Encoding.UTF8)
            );
        });

        context.RegisterSourceOutput(
            source: context
                .SyntaxProvider
                .CreateSyntaxProvider(
                    predicate: static (node, _) => node is AttributeSyntax { Parent.Parent: ParameterSyntax },
                    transform: TagAttributeValidation.ValidateDeclaration
                )
                .Where(static diagnostic => diagnostic is not null),
            action: static (output, diagnostic) =>
            {
                output.ReportDiagnostic(diagnostic!);
            }
        );

        var registrations = context
            .SyntaxProvider
            .CreateSyntaxProvider(
                predicate: static (node, _) => FactoryDiscovery.IsRegistrationCandidate(node),
                transform: FactoryDiscovery.Discover
            )
            .Where(static registration => registration is not null)
            .Select(static (registration, _) => registration!);

        var generation = registrations
            .Collect()
            .Combine(context.CompilationProvider)
            .Select(static (data, cancellationToken) => FactoryDiscovery.CreateDefinitions(
                registrations: data.Left,
                compilation: (CSharpCompilation)data.Right,
                cancellationToken
            ))
            .WithTrackingName("FactoryGeneration");

        context.RegisterSourceOutput(
            source: generation,
            action: static (output, result) =>
            {
                foreach (var diagnostic in result.Diagnostics)
                {
                    output.ReportDiagnostic(diagnostic);
                }
            }
        );

        var assemblyIdentity = context
            .CompilationProvider
            .Select(static (compilation, _) => compilation.Assembly.Identity.ToString());

        var definitions = generation
            .Select(static (result, _) => result.Definitions)
            .WithComparer(FactoryDefinitionsComparer.Instance);

        var factoriesSource = definitions
            .Select(static (factories, _) => FactoriesRenderer.Render(factories))
            .WithTrackingName("FactoriesSource");

        context.RegisterSourceOutput(
            source: assemblyIdentity.Combine(factoriesSource),
            action: static (output, data) =>
            {
                var hintName = HintNameHelper.GetAssemblyHintName(sourceName: "Factories", data.Left);

                output.AddSource(
                    hintName: $"{hintName}.g.cs",
                    sourceText: SourceText.From(data.Right, Encoding.UTF8)
                );
            }
        );
    }
}
